import runpy
namespace = runpy.run_path('tests/test_inventory_and_profiles.py')
case_type = namespace['CheckedInInventoryTests']
case_type.setUpClass()
case = case_type('test_working_discovery_binds_every_entry_and_introduced_id')
original = case.assertEqual
def capture(actual, expected, message=None):
    if isinstance(actual, dict) and 'subprocess_direct_site_count' in actual:
        print(repr(actual))
        raise SystemExit(0)
    return original(actual, expected, message)
case.assertEqual = capture
case.test_working_discovery_binds_every_entry_and_introduced_id()
